    /-- The empty type is a subtype of the top type. -/
    theorem none_subtype_term (d : Dispatcher) :
        Elixir.Module.Types.Descr.«subtype?/2» d (.map []) (.atom "term") = .ok (.atom "true") := by
      obtain ⟨T, term, bitmapT, -, -, staticT⟩ := unfolded_term_fields
