          (∃ s : Nat, s ≠ 0 ∧ Erlang.erlang.«map_size/1» (.map M) = .ok (.integer s)) := by
      cases M with
      | nil => exact Or.inl ⟨rfl, fun q => by simp [mapLookup]⟩
      | cons e rest =>
        right
        refine ⟨_, ?_, rfl⟩
        simp [List.eraseDupsBy, List.eraseDupsBy.loop]
        exact fun h => loop_ne_nil _ _ _ [] h

