          have : l₂ = [] := by rcases empty with rfl | h; simp at me; exact h
          exact ⟨s, fun o ⟨g₁, g₂⟩ => fsem_required h₁ me he ek (by rwa [absent l₂ this s o g₂] at g₁)⟩
