        intro l₁ l₂ size h₁ h₂
        exact tailCase l₁ l₂ h₁ h₂ (Or.inl (List.eq_nil_of_length_eq_zero (by omega)))
      | succ N ih =>
        intro l₁ l₂ size h₁ h₂
        match l₁, l₂ with
        | [], l₂ => exact tailCase [] l₂ h₁ h₂ (Or.inl rfl)
