    theorem all_optFlag {l : List (Term × Term)} (sl : FieldsV l) :
        (l.map fun e => Term.tuple #[e.1, e.2]).all (fun x => optFlag x) = Bool.true ↔
          ∀ e ∈ l, ∃ t, e.2 = .tuple #[t, boolAtom Bool.true] := by
