          obtain ⟨b, rfl⟩ := (h₂.1 _ List.mem_cons_self).1
          obtain ⟨t₁, o₁, rfl, f₁⟩ := (h₁.1 _ List.mem_cons_self).2
          obtain ⟨t₂, o₂, rfl, f₂⟩ := (h₂.1 _ List.mem_cons_self).2
          have sx := fieldsV_tail h₁
          have sy := fieldsV_tail h₂
          have hx := fieldsV_head h₁
